void
  server_object_loader::destroy ()
  {
    stop_attrinfo ();
    stop_scancache ();

    m_recdes_collected.clear ();
    m_retained_bytes = 0;

    m_clsid = NULL_CLASS_ID;
    m_class_entry = NULL;
    m_thread_ref = NULL;
  }

