heap_attrvalue_read_oos_inline (RECDES * recdes, int location, RECDES * raw, char *oos_scratch, int oos_scratch_size,
				bool * oos_owned_buffer)
{
  heap_oos_value_ref oos_ref;
  DB_BIGINT oos_len = 0;
  int error = NO_ERROR;
  THREAD_ENTRY *thread_p;

  *oos_owned_buffer = false;

