  int error = NO_ERROR;
  int i;

  assert (grouped_applied != NULL);
  assert (recdes != NULL && recdes->data != NULL && heap_recdes_contains_oos (recdes));
  *grouped_applied = false;

  for (i = 0; i < attr_info->num_values; i++)
    {
      if (heap_oos_attr_has_inline_ref (recdes, &attr_info->values[i]))
	{
	  requested_oos_count++;
	}
    }

  if (requested_oos_count < 2)
    {
      return NO_ERROR;
    }
  *grouped_applied = true;

  try
    {
      oos_payloads.resize ((std::size_t) attr_info->num_values, empty_payload);
      requests.reserve ((std::size_t) requested_oos_count);
    }
  catch (std::bad_alloc &)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1,
	      (size_t) attr_info->num_values * sizeof (RECDES)
	      + (size_t) requested_oos_count * sizeof (oos_read_request));
      return ER_OUT_OF_VIRTUAL_MEMORY;
    }

  for (i = 0; i < attr_info->num_values && error == NO_ERROR; i++)
    {
      heap_oos_value_ref ref;
      std::size_t oos_len = 0;

      if (!heap_oos_attr_has_inline_ref (recdes, &attr_info->values[i]))
	{
	  continue;		/* not OOS here: the per-attribute reader handles it */
	}

      error = heap_oos_value_ref::decode (*recdes, attr_info->values[i].read_attrepr->location, ref);
      oos_len = ref.length ();
      if (error == NO_ERROR && recdes_allocate_data_area (&oos_payloads[i], (int) oos_len) != NO_ERROR)
	{
	  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, (size_t) oos_len);
	  error = ER_OUT_OF_VIRTUAL_MEMORY;
	}
      if (error == NO_ERROR)
	{
	  oos_payloads[i].length = (int) oos_len;
	  oos_buffer dest (oos_payloads[i].data, oos_len);
	  if (ref.m_kind == heap_oos_value_ref::kind::memory)
	    {
	      error = ref.read_into (thread_p, dest);
	    }
	  else
	    {
	      requests.push_back ({ ref.m_value.disk, dest });
	    }
	}
    }

  if (error == NO_ERROR && !requests.empty ())
    {
      error = oos_read_many (thread_p, cubbase::span<oos_read_request> (requests.data (), requests.size ()));
    }

  return error;
}

int
heap_oos_value_ref::decode (const RECDES &record, int location, heap_oos_value_ref &ref)
{
  char *stub = nullptr;
  DB_BIGINT length = 0;
  OID head = OID_INITIALIZER;
  if (heap_recdes_get_oos_inline_stub (&record, location, &stub) != NO_ERROR)
    {
      goto invalid;
    }
  OR_GET_OID (stub, &head);
  OR_GET_BIGINT (stub + OR_OID_SIZE, &length);
  if (length <= 0 || length > DB_MAX_STRING_LENGTH)
    {
      goto invalid;
    }
  ref.m_length = (std::size_t) length;
  if (OID_ISNULL (&head))
    {
      /* Only a descriptor constructed locally by the pending serializer may
       * carry a memory alternative. Fetched and received records stay disk-only. */
      DB_BIGINT address = 0;
      if (record.type != REC_OOS_PENDING)
	{
	  goto invalid;
	}
      OR_GET_BIGINT (stub + OR_OID_SIZE + OR_BIGINT_SIZE, &address);
      if (address == 0)
	{
	  goto invalid;
	}
      ref.m_kind = kind::memory;
      ref.m_value.memory = reinterpret_cast<const char *> ((std::uintptr_t) address);
      return NO_ERROR;
    }
  {
    oos_chain_ref disk;
    int error = heap_oos_parse_inline_ref (&record, location, &disk, &length);
    if (error == NO_ERROR)
      {
	ref.m_value.disk = disk;
	ref.m_kind = kind::disk;
      }
    return error;
  }

invalid:
  er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_HEAP_OOS_BAD_INLINE_HEADER, 3, OID_AS_ARGS (&head));
  return ER_HEAP_OOS_BAD_INLINE_HEADER;
}

void
heap_oos_value_ref::encode_memory (char *stub, oos_buffer value)
{
  static_assert (sizeof (std::uintptr_t) <= sizeof (DB_BIGINT), "OOS accessor must fit its packed field");
  OR_BUF buf;
  or_init (&buf, stub, OR_OOS_INLINE_SIZE);
  or_put_oid (&buf, &oid_Null_oid);
  or_put_bigint (&buf, (DB_BIGINT) value.size ());
  or_put_bigint (&buf, (DB_BIGINT) reinterpret_cast<std::uintptr_t> (value.data ()));
}

int
heap_oos_value_ref::read_into (THREAD_ENTRY *thread_p, oos_buffer destination) const
{
  if (destination.size () != m_length || destination.data () == nullptr)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_GENERIC_ERROR, 0);
      return ER_GENERIC_ERROR;
    }
  switch (m_kind)
    {
    case kind::memory:
      std::memcpy (destination.data (), m_value.memory, m_length);
      return NO_ERROR;
    case kind::disk:
      return oos_read (thread_p, m_value.disk, destination);
    }
  return ER_FAILED;
}

class heap_oos_value_ref
{
  public:
    heap_oos_value_ref () : m_kind (kind::disk), m_length (0), m_value () {}
    static int decode (const RECDES &record, int location, heap_oos_value_ref &ref);
    static void encode_memory (char *stub, oos_buffer value);
    std::size_t length () const
    {
      return m_length;
    }
    int read_into (THREAD_ENTRY *thread_p, oos_buffer destination) const;

  private:
    enum class kind { memory, disk };
    kind m_kind;
    std::size_t m_length;
    union value
    {
      const char *memory;
      oos_chain_ref disk;
      value () : disk {} {}
    } m_value;
    friend int heap_oos_read_grouped_payloads (THREAD_ENTRY *, RECDES *, HEAP_CACHE_ATTRINFO *,
	std::vector<RECDES> &, bool *);
    friend int heap_oos_finalize_record (THREAD_ENTRY *, const OID *, RECDES *);
}

std::size_t length () const
    {
      return m_length;
    }

union value
    {
      const char *memory;
      oos_chain_ref disk;
      value () : disk {} {}
    }

heap_pending_record::heap_pending_record ()
  : m_record (cubmem::STANDARD_BLOCK_ALLOCATOR)
{
  m_record.set_external_buffer (nullptr, 0);
}

heap_pending_record::heap_pending_record (heap_pending_record &&other) noexcept
  : m_record (std::move (other.m_record))
  , m_bytes (other.m_bytes)
{
  m_values.swap (other.m_values);
  other.m_bytes = 0;
}

int
heap_pending_record::retain (oos_buffer value)
{
  try
    {
      m_values.push_back (value);
    }
  catch (const std::bad_alloc &)
    {
      er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_OUT_OF_VIRTUAL_MEMORY, 1, sizeof (oos_buffer));
      return ER_OUT_OF_VIRTUAL_MEMORY;
    }
  m_bytes += value.size ();
  return NO_ERROR;
}

heap_pending_record::~heap_pending_record ()
{
  for (auto &value : m_values)
    {
      char *data = value.data ();
      free_and_init (data);
    }
}

class heap_pending_record
{
  public:
    heap_pending_record ();
    ~heap_pending_record ();
    heap_pending_record (heap_pending_record &&other) noexcept;
    heap_pending_record (const heap_pending_record &) = delete;
    heap_pending_record &operator= (const heap_pending_record &) = delete;

    record_descriptor &record ()
    {
      return m_record;
    }
    const RECDES &get_recdes () const
    {
      return m_record.get_recdes ();
    }
    std::size_t retained_bytes () const
    {
      return m_record.get_recdes ().area_size + m_bytes + m_values.capacity () * sizeof (oos_buffer);
    }
    int retain (oos_buffer value);

  private:
    record_descriptor m_record;
    std::vector<oos_buffer> m_values;
    std::size_t m_bytes = 0;
}

